namespace Inventory;

/// <summary>Builds a replenishment plan across a set of stock items.</summary>
public sealed class ReplenishmentPlanner
{
    public IReadOnlyList<string> BuildPlan(IEnumerable<StockItem> items, ISupplier supplier, int season)
    {
        var plan = new List<string>();
        foreach (var item in items)
        {
            var entry = BuildPlanEntry(item, supplier, season);
            if (entry is not null)
                plan.Add(entry);
        }

        return plan;
    }

    private static string? BuildPlanEntry(StockItem item, ISupplier supplier, int season)
    {
        if (item.OnHand < 0)
            return null;

        int available = item.OnHand - item.Reserved;
        if (available > item.ReorderPoint)
            return null;

        int deficit = item.ReorderPoint - available;
        int orderQty = ApplySeasonalAdjustment(CalculateOrderQuantity(deficit), season);
        if (orderQty <= 0)
            return null;
        if (string.IsNullOrEmpty(item.Sku))
            return null;

        bool placed = supplier.PlaceOrder(item.Sku, orderQty);
        return FormatPlanEntry(item.Sku, orderQty, placed);
    }

    private static int CalculateOrderQuantity(int deficit)
    {
        if (deficit <= 0)
            return 0;
        if (deficit < 10)
            return 10;
        if (deficit < 100)
            return deficit;

        return deficit + 50;
    }

    private static int ApplySeasonalAdjustment(int orderQty, int season)
    {
        if (season == 4 && orderQty > 0)
            return (int)(orderQty * 1.5);
        if (season == 1)
            return orderQty / 2;

        return orderQty;
    }

    private static string FormatPlanEntry(string sku, int orderQty, bool placed)
    {
        if (placed && orderQty > 200)
            return $"{sku}:LARGE:{orderQty}";
        if (placed)
            return $"{sku}:{orderQty}";

        return $"{sku}:FAILED";
    }
}
